const app=document.querySelector('#app');let group='전체',query='',sort='기본순';let saved=new Set(JSON.parse(localStorage.getItem('theme-saved')||'[]'));const fmt=n=>n.toLocaleString('ko-KR');const av=(p,extra='')=>`<div class="avatar ${extra}" role="img" aria-label="${p.name}의 대화 캐릭터 일러스트" style="background-position:${p.id%4*100/3}% ${Math.floor(p.id/4)*50}%"></div>`;const aliases={6:'고형',7:'해병님'};const star=id=>saved.has(id)?'★':'☆';
function save(id){saved.has(id)?saved.delete(id):saved.add(id);localStorage.setItem('theme-saved',JSON.stringify([...saved]));if(location.hash.startsWith('#person/'))render();else list();toast(saved.has(id)?'내 도감에 저장했어요':'내 도감에서 뺐어요')}
function toast(t){document.querySelector('.toast')?.remove();let el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=t;document.body.append(el);setTimeout(()=>el.remove(),1800)}
function home(){app.innerHTML=`<section class="hero"><div><div class="eyebrow">개별의 테마천국 / PEOPLE ARCHIVE</div><h1>대화 속 캐릭터,<br><em>한 권의 위키가 되다.</em></h1><p>떠들고, 웃고, 따지고, 또 함께했던 우리.<br>열두 사람의 조금 특별한 인물도감을 펼쳐보세요.</p></div><div class="heropicture">${[people[0],people[4],people[1]].map(p=>av(p,'heroavatar')).join('')}<span class="heroCaption">12 PEOPLE. COUNTLESS CONVERSATIONS.</span></div></section><div class="stats"><div><strong>12</strong><span>기록된 인물</span></div><div><strong>2023—26</strong><span>앞선 분석의 대화 범위</span></div><div><strong>01</strong><span>우리들의 세계</span></div></div><div class="sectionhead"><h2>인물도감 <span style="color:#8c9b85;font-size:16px">12</span></h2><div><small>카드를 누르면 위키 문서가 열립니다</small><a class="comparelink" href="#compare">인물 비교 ↗</a></div></div><div class="toolbar"><div class="filters">${['전체','분위기','논객','분석','취향','내 도감'].map(g=>`<button class="chip ${g===group?'active':''}" data-group="${g}">${g==='분위기'?'분위기 메이커':g==='분석'?'분석·정보':g==='취향'?'취향·표현':g}</button>`).join('')}</div><div class="searchwrap"><input type="search" id="search" aria-label="인물 이름 또는 성향 검색" placeholder="⌕  이름, 별명, 성향 검색" value=""><select id="sort" aria-label="정렬"><option>기본순</option><option>발언 많은 순</option><option>이름순</option></select></div></div><div class="grid" id="cards"></div><aside class="note"><b>이 도감의 읽는 법</b><br>실제 성격 진단이 아닌, 단톡방에서 드러난 대화 캐릭터를 모았습니다. 일러스트는 실제 외모와 무관한 창작 아바타입니다. 통계와 해석은 전달된 기존 분석을 옮긴 것으로, 이번 제작에서 전체 CSV를 재집계하지 않았습니다. <a href="#guide" style="text-decoration:underline">출처와 기준 보기 ↗</a></aside>`;document.querySelector('#search').value=query;document.querySelector('#sort').value=sort;document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{group=b.dataset.group;home()});document.querySelector('#search').oninput=e=>{query=e.target.value;list()};document.querySelector('#sort').onchange=e=>{sort=e.target.value;list()};list()}
function list(){let result=people.filter(p=>(group==='전체'||group===p.group||(group==='내 도감'&&saved.has(p.id)))&&[p.name,p.type,p.role,...p.tags,aliases[p.id]||''].join(' ').includes(query.trim()));if(sort==='발언 많은 순')result.sort((a,b)=>b.count-a.count);if(sort==='이름순')result.sort((a,b)=>a.name.localeCompare(b.name,'ko'));document.querySelector('#cards').innerHTML=result.length?result.map(p=>`<article class="card"><button class="bookmark" aria-label="${p.name} ${saved.has(p.id)?'저장 해제':'저장'}" data-save="${p.id}">${star(p.id)}</button><a href="#person/${p.id}"><div class="portrait"><span class="no">NO. ${String(p.id+1).padStart(2,'0')}</span>${av(p)}</div><div class="cardbody"><span class="role">${p.role}</span><h3>${p.name} ${aliases[p.id]?`<small style="font-size:11px;color:#87917f;font-weight:normal">${aliases[p.id]}</small>`:''}</h3><p>${p.type}</p><div class="tags">${p.tags.map(t=>`<span>#${t}</span>`).join('')}</div><div class="cardbottom"><span>메시지 <b>${fmt(p.count)}</b></span><span class="arrow">↗</span></div></div></a></article>`).join(''):'<div class="empty">해당하는 인물이 없어요.<br><br>다른 이름이나 성향으로 찾아보세요.</div>';document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>save(Number(b.dataset.save)))}
function person(id){const p=people[id];if(!p){location.hash='';return}const related=people.filter(x=>x.id!==id&&x.group===p.group);document.title=`${p.name} — 개별의테마천국 위키`;app.innerHTML=`<a class="back" href="#">← 인물도감으로</a><div class="crumb">인물 / ${p.group} / ${p.name}</div><div class="dochead"><div><div class="eyebrow">CHARACTER DOCUMENT / ${String(id+1).padStart(2,'0')}</div><h1>${p.name} ${aliases[id]?`<small style="font-size:20px;color:#8b9686">(${aliases[id]})</small>`:''}</h1><div class="sub">${p.type}</div></div><button class="btn outline" id="saveDoc">${star(id)} 내 도감 ${saved.has(id)?'저장됨':'저장'}</button></div><div class="docgrid"><aside class="toc"><b>목차</b>${['개요','대화 스타일','강점과 다른 시선','기록','함께 읽기'].map((s,i)=>`<a href="#section-${i}" data-anchor="section-${i}">${i+1}. ${s}</a>`).join('')}<a href="#guide">출처와 편집 기준 ↗</a></aside><article class="article"><div class="quote">${p.line}<small>대화 캐릭터를 표현한 편집 문구 · 실제 발언 인용 아님</small></div><h2 id="section-0"><span>1.</span>개요</h2><p>${p.about}</p><div class="tags">${p.tags.map(t=>`<span>#${t}</span>`).join('')}</div><h2 id="section-1"><span>2.</span>대화 스타일</h2><p>${p.style}</p><h2 id="section-2"><span>3.</span>강점과 다른 시선</h2><p>${p.balance}</p><h2 id="section-3"><span>4.</span>기록</h2><p>기존 분석에 전달된 메시지 수는 <b>${fmt(p.count)}건</b>, 평균 메시지 길이는 <b>${p.length}자</b>다. 웃음(ㅋ)이 포함된 메시지는 <b>${p.laugh}%</b>로 집계되어 있다.</p><p>${p.swear===null?'강한 욕설 비율은 기존 분석에 제공되지 않았다.':`대표적인 강한 욕설 표현을 포함한 비율은 ${p.swear}%다. 이 수치는 모든 비속어를 포함한 비율이 아니다.`}</p><p>발언량과 표현 빈도는 참여 방식에 대한 참고 자료다. 실제 친밀도, 영향력, 내향성이나 공격성의 점수로 해석하지 않는다.</p><h2 id="section-4"><span>5.</span>함께 읽기</h2><p>비슷한 대화 역할로 분류된 인물의 문서. 실제 친분 관계를 의미하지 않는다.</p><div class="related">${related.map(r=>`<a href="#person/${r.id}">${r.name} ↗</a>`).join('')}</div><div class="note" style="margin:28px 0 0">출처: 이 대화에 전달된 기존 인물 분석. 실제 어록·사건·인간관계는 원문 맥락을 확인한 뒤 추가할 수 있도록 이번 문서에서 제외했습니다. <a href="#guide">편집 기준 ↗</a></div></article><aside class="profile"><div class="portrait">${av(p)}</div><h3>${p.name}</h3><div class="type">${p.role}</div><div class="facts"><div class="fact"><span>분류</span><b>단톡방 인물</b></div><div class="fact"><span>별명</span><b>${aliases[id]||'미등록'}</b></div><div class="fact"><span>메시지</span><b>${fmt(p.count)}건</b></div><div class="fact"><span>평균 길이</span><b>${p.length}자</b></div><div class="fact"><span>웃음 포함</span><b>${p.laugh}%</b></div><div class="fact"><span>자료 상태</span><b>기존 분석 인용</b></div></div></aside></div><div style="height:60px"></div>`;document.querySelector('#saveDoc').onclick=()=>save(id);document.querySelectorAll('[data-anchor]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.anchor).scrollIntoView({behavior:'smooth'})})}
function compare(){app.innerHTML=`<a class="back" href="#">← 인물도감으로</a><section class="compare"><div class="eyebrow">SIDE BY SIDE</div><h1>나란히 펼쳐보기</h1><p class="sub">능력치 대신 대화에서 드러난 특징을 비교합니다.</p><div style="display:flex;gap:16px;margin-top:28px"><select id="a" aria-label="첫 번째 인물">${people.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select><select id="b" aria-label="두 번째 인물">${people.map(p=>`<option value="${p.id}" ${p.id===4?'selected':''}>${p.name}</option>`).join('')}</select></div><div id="comparison"></div><div class="note">통계는 기존 분석 인용값이며, 실제 인격이나 두 사람의 우열을 의미하지 않습니다.</div></section>`;document.querySelector('#a').onchange=compareRows;document.querySelector('#b').onchange=compareRows;compareRows()}
function compareRows(){let a=people[Number(document.querySelector('#a').value)],b=people[Number(document.querySelector('#b').value)];const rows=[['캐릭터',a.type,b.type],['대화 역할',a.role,b.role],['메시지 수',fmt(a.count)+'건',fmt(b.count)+'건'],['평균 메시지 길이',a.length+'자',b.length+'자'],['웃음 포함 비율',a.laugh+'%',b.laugh+'%'],['핵심 태그',a.tags.join(' · '),b.tags.join(' · ')]];document.querySelector('#comparison').innerHTML=`<table class="comparetable"><thead><tr><th>기준</th>${[a,b].map(p=>`<th>${av(p)}<a href="#person/${p.id}">${p.name} ↗</a></th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((v,i)=>`<${i?'td':'th'}>${v}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table>`}
function guide(){app.innerHTML=`<a class="back" href="#">← 인물도감으로</a><article class="article guide"><div class="eyebrow">ABOUT THE ARCHIVE</div><h1>우리 이야기를 기록하는 방식</h1><h2>위키와 인물도감</h2><p>개별의테마천국 위키는 개별의 테마천국 참여자 12명의 대화 캐릭터를 소개하는 개인 아카이브입니다. 인물 카드에서 각자의 상세 문서로 이동하고, 두 사람을 나란히 비교할 수 있습니다.</p><h2>자료와 출처</h2><p>이 사이트의 인물별 해석과 숫자는 2026년 10월 19일 이 대화에 전달된 기존 분석을 바탕으로 작성했습니다. 원본은 KakaoTalk_Chat_개별의 테마천국_2026-10-19-15-09-48.csv이며, 이번 제작에서는 파일의 형식과 일부 내용만 확인했습니다. 전체 메시지 재집계나 분석 정확도 검증을 완료한 데이터로 표시하지 않습니다.</p><p>메시지 수, 평균 길이, 웃음·욕설 비율은 기존 분석의 인용값입니다. 봇 제외와 닉네임 통합은 기존 분석 기준을 따랐으며, 여기에서 별도로 검증하지 않았습니다. 전체 대화 수와 전체 참여자 수는 확정 통계로 싣지 않았습니다.</p><h2>캐릭터와 실제 인물</h2><p>분류와 설명은 단톡방 대화 스타일에 대한 해석입니다. 실제 인격, 정신 건강, 사회성이나 관계의 질을 판단하지 않습니다. 적은 발언량이 낮은 관심이나 소극적인 성격을 뜻하지도 않습니다. 특히 최승영·이근호는 분석 표본과 기간의 한계가 큽니다.</p><h2>아바타</h2><p>12개 아바타는 대화 캐릭터에 맞춰 생성한 창작 일러스트입니다. 실제 외모를 재현하거나 추정한 이미지가 아닙니다. 비판형·활력형·설명형·장난형·분석형·신중형·반응형·취향형·관찰형·정보형·표현형·친화형을 같은 그림체로 표현했습니다.</p><h2>어록과 사건</h2><p>검증하지 않은 어록, 사건, 친밀도와 갈등 관계는 추가하지 않았습니다. 문서 상단의 한 줄 소개는 편집 문구이며 실제 발언 인용이 아닙니다. 원문 인용을 추가할 때에는 화자, 시각, 앞뒤 맥락을 함께 확인해야 합니다.</p><h2>내 도감</h2><p>별표를 누르면 이 브라우저의 저장 공간에 북마크가 남습니다. 계정 간 또는 기기 간 동기화 기능은 없습니다. 원본 대화 CSV는 사이트에 포함하지 않았습니다.</p></article>`}
function render(){document.title='개별의테마천국 위키 · 인물도감';let h=location.hash;if(h.startsWith('#person/'))person(Number(h.split('/')[1]));else if(h==='#compare')compare();else if(h==='#guide')guide();else home();window.scrollTo(0,0)}window.addEventListener('hashchange',render);render();
